        /// <summary>
        /// Compares a fitted analysis with a reference for the first <paramref name="k"/> components.
        /// </summary>
        private static void AssertMatches(Reference expected, PrincipalComponentAnalysis pca, int k)
        {
            for (int i = 0; i < k; i++)
            {
                Assert.AreEqual(expected.ExplainedVariance[i], pca.ExplainedVariance[i], 1E-12 * expected.ExplainedVariance[0]);
                Assert.AreEqual(expected.ExplainedVarianceRatio[i], pca.ExplainedVarianceRatio[i], 1E-12);
                Assert.AreEqual(expected.SingularValues[i], pca.SingularValues[i], 1E-12 * expected.SingularValues[0]);
                for (int j = 0; j < pca.NumberOfFeatures; j++)
                    Assert.AreEqual(expected.Components[i, j], pca.Components[i, j], 1E-10);
                for (int r = 0; r < 3; r++)
                    Assert.AreEqual(expected.ScoresFirst3[r, i], pca.Scores[r, i], 1E-10);
            }
        }

        /// <summary>
        /// Iris on the covariance basis matches scikit-learn, including the axis signs.
        /// </summary>
        [TestMethod]
        public void Test_Iris_Covariance()
        {
            var pca = new PrincipalComponentAnalysis(Iris);
            pca.Train();
            Assert.AreEqual(4, pca.NumberOfComponents);
            AssertMatches(IrisCovariance, pca, 4);
            Assert.AreEqual(4.561168232662192, pca.TotalVariance, 1E-12);
        }

        /// <summary>
        /// Iris on the correlation basis matches scikit-learn on standardized data and prcomp(scale. = TRUE).
        /// </summary>
        [TestMethod]
        public void Test_Iris_Correlation()
        {
            var pca = new PrincipalComponentAnalysis(new Matrix(Iris), PrincipalComponentBasis.Correlation);
            pca.Train();
            AssertMatches(IrisCorrelation, pca, 4);
            Assert.AreEqual(4.0, pca.TotalVariance, 1E-12);
            // prcomp sdev^2
            Assert.AreEqual(2.9142009996559892, pca.ExplainedVariance[0], 1E-12);
            Assert.AreEqual(0.020748155920011512, pca.ExplainedVariance[3], 1E-13);
            // On the correlation basis the loadings are variable-component correlations, so each row has unit sum of squares.
            for (int j = 0; j < 4; j++)
            {
                double s = 0;
                for (int i = 0; i < 4; i++) s += pca.Loadings[j, i] * pca.Loadings[j, i];
                Assert.AreEqual(1.0, s, 1E-12);
            }
        }

        /// <summary>
        /// The random matrix on both bases matches scikit-learn.
        /// </summary>
        [TestMethod]
        public void Test_Random_BothBases()
        {
            var cov = new PrincipalComponentAnalysis(RandomMatrix);
            cov.Train();
            AssertMatches(RandomCovariance, cov, 5);
            var cor = new PrincipalComponentAnalysis(RandomMatrix, PrincipalComponentBasis.Correlation);
            cor.Train();
            AssertMatches(RandomCorrelation, cor, 5);
        }

        /// <summary>
        /// The prcomp rotation agrees up to a sign per component.
        /// </summary>
        [TestMethod]
        public void Test_Iris_Prcomp_UpToSign()
        {
            // prcomp(iris[, 1:4])$rotation, column-major.
            var rotation = new double[] { 0.36012004211765358, -0.083890930300149602, 0.85705669572373311, 0.35878919631682132, -0.65522386510183117, -0.73169210059644052, 0.17251409435203657, 0.074479821265107216, 0.58418663409241101, -0.59645768918970798, -0.075609216767020926, -0.54520404244111309, 0.31578666598508592, -0.31910375545364184, -0.47955808188882626, 0.75397322295723213 };
            var pca = new PrincipalComponentAnalysis(Iris);
            pca.Train();
            for (int i = 0; i < 4; i++)
            {
                double sign = Math.Sign(rotation[i * 4] * pca.Components[i, 0]);
                for (int j = 0; j < 4; j++)
                    Assert.AreEqual(rotation[i * 4 + j], sign * pca.Components[i, j], 1E-10);
            }
        }

        /// <summary>
        /// With more variables than observations, the n − 1 nonzero components match scikit-learn and the remaining
        /// variance is zero.
        /// </summary>
        [TestMethod]
        public void Test_Wide_PGreaterThanN()
        {
            var X = new double[4, 5];
            for (int r = 0; r < 4; r++)
                for (int c = 0; c < 5; c++)
                    X[r, c] = RandomMatrix[r, c];
            var pca = new PrincipalComponentAnalysis(X);
            pca.Train();
            Assert.AreEqual(4, pca.NumberOfComponents);
            AssertMatches(WideCovariance, pca, 3);
            Assert.AreEqual(0.0, pca.ExplainedVariance[3], 1E-12);
        }

        /// <summary>
        /// Transform followed by inverse transform reproduces the data with all components, and reproduces the
        /// rank-k projection with fewer.
        /// </summary>
        [TestMethod]
        public void Test_InverseTransform()
        {
            var pca = new PrincipalComponentAnalysis(RandomMatrix, PrincipalComponentBasis.Correlation);
            pca.Train();
            var back = pca.InverseTransform(pca.Scores);
            for (int r = 0; r < 12; r++)
                for (int c = 0; c < 5; c++)
                    Assert.AreEqual(RandomMatrix[r, c], back[r, c], 1E-10);

            var two = new PrincipalComponentAnalysis(RandomMatrix, numberOfComponents: 2);
            two.Train();
            Assert.AreEqual(2, two.Components.GetLength(0));
            var row = new double[] { RandomMatrix[0, 0], RandomMatrix[0, 1], RandomMatrix[0, 2], RandomMatrix[0, 3], RandomMatrix[0, 4] };
            var t = two.Transform(row);
            Assert.AreEqual(RandomCovariance.ScoresFirst3[0, 0], t[0], 1E-10);
            Assert.AreEqual(RandomCovariance.ScoresFirst3[0, 1], t[1], 1E-10);
            // Projecting the reconstruction again returns the same scores.
            var again = two.Transform(two.InverseTransform(t));
            Assert.AreEqual(t[0], again[0], 1E-10);
            Assert.AreEqual(t[1], again[1], 1E-10);
            Assert.AreEqual(RandomCovariance.ExplainedVarianceRatio[0] + RandomCovariance.ExplainedVarianceRatio[1], two.CumulativeExplainedVarianceRatio[1], 1E-12);
        }

        /// <summary>
        /// The largest-magnitude element of every axis is positive.
        /// </summary>
        [TestMethod]
        public void Test_SignConvention()
        {
            var pca = new PrincipalComponentAnalysis(Iris, PrincipalComponentBasis.Correlation);
            pca.Train();
            for (int i = 0; i < 4; i++)
            {
                int imax = 0;
                for (int j = 1; j < 4; j++)
                    if (Math.Abs(pca.Components[i, j]) > Math.Abs(pca.Components[i, imax])) imax = j;
                Assert.IsGreaterThan(0.0, pca.Components[i, imax]);
            }
        }

        /// <summary>
        /// A constant column has zero variance on the covariance basis and duplicate rows are allowed. A large problem
        /// that uses the parallel blocked cross product matches a direct two-pass covariance and is reproducible.
        /// </summary>
        [TestMethod]
        public void Test_ConstantColumn_Duplicates_LargeAndReproducible()
        {
            var X = new double[,] { { 1, 5, 2 }, { 2, 5, 2 }, { 3, 5, 7 }, { 3, 5, 7 } };
            var pca = new PrincipalComponentAnalysis(X);
            pca.Train();
            Assert.AreEqual(0.0, pca.ExplainedVariance[2], 1E-14);
            Assert.AreEqual(0.0, pca.Components[0, 1], 1E-14);

            int n = 20000, p = 7;
            var rng = new Random(7);
            var big = new double[n, p];
            for (int r = 0; r < n; r++)
            {
                double f = rng.NextDouble();
                for (int c = 0; c < p; c++) big[r, c] = 1000.0 + c * f + rng.NextDouble();
            }
            var a = new PrincipalComponentAnalysis(big);
            a.Train();
            var b = new PrincipalComponentAnalysis(big);
            b.Train();
            for (int i = 0; i < p; i++) Assert.AreEqual(a.ExplainedVariance[i], b.ExplainedVariance[i], 0.0);

            var mean = new double[p];
            for (int r = 0; r < n; r++) for (int c = 0; c < p; c++) mean[c] += big[r, c] / n;
            double trace = 0;
            for (int c = 0; c < p; c++)
            {
                double s = 0;
                for (int r = 0; r < n; r++) s += (big[r, c] - mean[c]) * (big[r, c] - mean[c]);
                trace += s / (n - 1);
            }
            Assert.AreEqual(trace, a.TotalVariance, 1E-12 * trace);
            double sum = 0;
            for (int i = 0; i < p; i++) sum += a.ExplainedVariance[i];
            Assert.AreEqual(trace, sum, 1E-12 * trace);
        }

        /// <summary>
        /// Invalid inputs are rejected.
        /// </summary>
        [TestMethod]
        public void Test_InvalidInputs()
        {
            Assert.ThrowsExactly<ArgumentNullException>(() => new PrincipalComponentAnalysis((double[,])null!));
            Assert.ThrowsExactly<ArgumentException>(() => new PrincipalComponentAnalysis(new double[1, 3]));
            Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => new PrincipalComponentAnalysis(RandomMatrix, numberOfComponents: 6));
            var constant = new double[,] { { 1, 5 }, { 2, 5 }, { 3, 5 } };
            Assert.ThrowsExactly<ArgumentException>(() => new PrincipalComponentAnalysis(constant, PrincipalComponentBasis.Correlation).Train());
            var nan = new double[,] { { 1, 2 }, { double.NaN, 5 }, { 3, 5 } };
            Assert.ThrowsExactly<ArgumentException>(() => new PrincipalComponentAnalysis(nan).Train());
            var untrained = new PrincipalComponentAnalysis(RandomMatrix);
            Assert.ThrowsExactly<InvalidOperationException>(() => untrained.Transform(new double[5]));
            Assert.ThrowsExactly<InvalidOperationException>(() => _ = untrained.Scores);
            var trained = new PrincipalComponentAnalysis(RandomMatrix);
            trained.Train();
            Assert.ThrowsExactly<ArgumentException>(() => trained.Transform(new double[4]));
            Assert.ThrowsExactly<ArgumentException>(() => trained.InverseTransform(new double[3]));
        }

        /// <summary>
        /// The covariance and correlation decompositions keep their bits: the matrix is formed from its lower triangle and
        /// mirrored, so it is exactly symmetric, and the components and explained variances equal the pinned values.
        /// </summary>
        [TestMethod]
        public void Test_Train_BitwiseRegression()
        {
            int p = 5;
            foreach (var (basis, pins) in new[]
            {
                (PrincipalComponentBasis.Covariance, new ulong[] { 0xbf999f4504d55bd5UL, 0xbfcad7b03092aa0fUL, 0x3fc27009d1fba49eUL, 0xbf9a6135c59e46faUL, 0x3feeecfbda9cb595UL, 0xbfa7d4060efa37e9UL, 0xbfc4e188f70faccbUL, 0x3fde65d5259d5261UL, 0x3feb7fd66cf044e6UL, 0xbfb5a10e4661997dUL, 0x3fb509e99106cec9UL, 0xbfbf9f1931a9ab16UL, 0x3fead4a1a25e7f75UL, 0xbfdfe64a731c8c00UL, 0xbfc4daf307f901b5UL, 0xbfd13aa082a1bc64UL, 0x3fed7a727a3b2751UL, 0x3fccb7304105a829UL, 0x3faaaf136323c702UL, 0x3fc497875a496502UL, 0x3feea8dff99cc388UL, 0x3fd062b6a7fd781cUL, 0x3f9260cc8b0275a6UL, 0x3fb9351148523cfbUL, 0x3fb48f4acfbb47deUL, 0x400690c51e212d6aUL, 0x3ffacef39baaaf97UL, 0x3fe608fea06a0eedUL, 0x3fc459b899804a60UL, 0x3fbb6dbd5d3f1734UL }),
                (PrincipalComponentBasis.Correlation, new ulong[] { 0x3fc66f834248006dUL, 0x3fe3c87f6f9658b9UL, 0xbfe06725703c9518UL, 0xbfd6d44d652715dbUL, 0xbfdc6990626b706eUL, 0xbfd686999c5cbc58UL, 0x3fceb76c930deda2UL, 0x3fc9caba2fbea515UL, 0x3fe5679a8bf2ef85UL, 0xbfe26591dfbe4dc9UL, 0x3feb47bf96347785UL, 0xbfb64f66ee6063f4UL, 0x3fd974f141255f89UL, 0x3fb6c16a3cfcc5feUL, 0xbfd43094b4c6a322UL, 0xbfd3e1edab4535a7UL, 0x3fc76316155f68adUL, 0x3fe620e2b590affdUL, 0xbfe31f9b168372c2UL, 0xbfc7deb9fe696566UL, 0x3fc308f8388f18a4UL, 0x3fe70ef9c56a8719UL, 0x3fcf6a9b8ee7843dUL, 0x3fcf6e81c3665ce4UL, 0x3fe29b6e0eae90b5UL, 0x3ffeec0ea89a15b8UL, 0x3ff2e805d62f5566UL, 0x3ff02692462386fcUL, 0x3fe1bdffb7990d1cUL, 0x3fd499657d1a1d5aUL }),
            })
            {
                var rng = new Random(p);
                int n = 3 * p + 10;
                var X = new double[n, p];
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < p; j++)
                        X[i, j] = 1e3 * j + rng.NextDouble() * (j + 1) + (j > 0 ? 0.3 * X[i, j - 1] : 0);
                var pca = new PrincipalComponentAnalysis(X, basis);
                pca.Train();
                int m = 0;
                foreach (var v in pca.Components)
                    Assert.AreEqual(unchecked((long)pins[m++]), BitConverter.DoubleToInt64Bits(v), $"{basis} component entry {m - 1}");
                foreach (var v in pca.ExplainedVariance)
                    Assert.AreEqual(unchecked((long)pins[m++]), BitConverter.DoubleToInt64Bits(v), $"{basis} explained variance {m - 1 - p * p}");
                Assert.AreEqual(pins.Length, m);
            }
        }

    }
